#!/bin/bash
# fix-microring-and-photo-v1.sh
#
# Two real bugs fixed, both verified by generating actual PDFs and
# comparing them against the live page -- not just changing code and
# assuming it works:
#
#   1. PHOTO CROP MISMATCH: html2canvas doesn't reliably replicate
#      object-fit/object-position on <img> tags. Fixed by switching to
#      CSS background-image.
#
#   2. MICROPRINT RING MISSING FROM PDF ENTIRELY: the circular security
#      text around the watermark seal used SVG <textPath>, which
#      html2canvas silently drops during capture -- it showed correctly
#      on the live page but vanished completely in the PDF. Fixed by
#      pre-rendering the ring as a static image (same proven approach as
#      the watermark seal itself) instead of live SVG text-on-path.
#
# Creates portal/assets/microring.png and overwrites portal/id-card-view.html.
# Safe to re-run.

set -e

echo "==> Creating portal/assets/microring.png"
mkdir -p portal/assets
base64 -d > portal/assets/microring.png << 'B64_EOF'
